INSERT INTO walk_acts (fence_id, companion_id, joke_id, act_index, version_id, content, label)
VALUES
('sy-01', 'sharp-elder', 'elder-a', 0, 'sy-01-elder-a-l1', '别急着往里走，先回头看一眼刚才穿过来的那道牌坊——文德坊。和对面武功坊一对，一文一武，把大清门夹在中间。这格局，跟北京故宫差远了，但人家就是这么过来的：先搭个框架，剩下的入关再说。创业公司嘛，办公室寒碜点不丢人。', NULL),
('sy-01', 'sharp-elder', 'elder-a', 1, 'sy-01-elder-a-l2', '你看这大清门，就五个开间，跟北京太和门一比跟门卫室似的。努尔哈赤那会儿刚从山林里杀出来，手底下没几个工匠，这门的规格已经是当时的顶配了。皇太极改国号为“清”之后，门口才敢刻“大清门”仨字——之前这里连个正式国号都没有，相当于公司注册了但连招牌都没挂。', '大清门为什么这么小'),
('sy-01', 'sharp-elder', 'elder-a', 2, 'sy-01-elder-a-l3', '这扇门有个容易漏掉的细节：门钉。横五竖九，四十五颗。按明清规制，皇家用九路，亲王用七路。沈阳故宫大清门的门钉是五路——因为在关外时，努尔哈赤名义上还只是后金的汗，不是大清的皇帝。皇太极称帝后也没改动，可能是觉得门口的东西不打紧，江山才是要紧的。结果这五路门钉成了历史切片，定格了清朝称帝前那一瞬间的“还不够格”。', NULL),
('sy-01', 'sharp-elder', 'elder-b', 0, 'sy-01-elder-b-l1', '别急着往里走，先回头看一眼刚才穿过来的那道牌坊——文德坊。和对面武功坊一对，一文一武，把大清门夹在中间。这格局，跟北京故宫差远了，但人家就是这么过来的：先搭个框架，剩下的入关再说。创业公司嘛，办公室寒碜点不丢人。', NULL),
('sy-01', 'sharp-elder', 'elder-b', 1, 'sy-01-elder-b-l2', '这地方占地面积只有北京故宫的十二分之一，说是皇宫，其实就是个稍大点儿的官署。但你注意啊，北京故宫盖了十四年，这里从努尔哈赤搬到沈阳到顺治入关，前后不到二十年。而且中间还在打仗，修修停停，能盖成这样已经不容易了。人家是毛坯房先住着，北京那套等上市了再说。', '沈阳故宫和北京故宫差在哪'),
('sy-01', 'sharp-elder', 'elder-b', 2, 'sy-01-elder-b-l3', '从1625年努尔哈赤迁都沈阳，到1644年顺治入关，满打满算十九年。这十九年里，后金/大清同时在打三场大仗：对明朝、对蒙古、对朝鲜。一边打仗一边盖皇宫，预算永远紧巴巴的。所以你看沈阳故宫有个特点：能用就行，不追求排场。入关后修的北京故宫，那是“花了十四年，动用了百万工匠，搬了一座景山来镇住前朝的龙脉”。一个是创业期的经济适用房，一个是上市后的总部大楼。懂这个差别，你就懂了清朝的全部历史。', NULL),
('sy-01', 'su-dongpo', 'su-a', 0, 'sy-01-su-a-l1', '这道门比我想象的矮了许多。我在汴京时见惯了大宋宫城的巍峨，但转念一想——成吉思汗的蒙古包更小，照样踏平了半个天下。门的高度，从来不等于主人的高度。', NULL),
('sy-01', 'su-dongpo', 'su-a', 1, 'sy-01-su-a-l2', '我生活的时代，辽、金、西夏环伺，大宋总觉得他们是蛮夷。可你看这大清门，它的主人就是从“蛮夷”起步，最终入主中原坐了天下。历史反复证明一件事：瞧不起别人的人，往往最先被瞧不起的人打脸。我当年主张对辽金持开放态度，被同僚弹劾“立场不坚定”。', '夷夏之间'),
('sy-01', 'su-dongpo', 'su-a', 2, 'sy-01-su-a-l3', '我在定州做官时，驻地和辽国边境只隔一条河。我发现辽国人用的犁铧比大宋的还先进，他们的骑兵马蹄铁用的是冷锻技术，比大宋的热锻耐磨。我写了一篇观察报告呈给朝廷，石沉大海。同僚们宁可相信辽人是“蛮夷”，也不愿意承认人家有值得学习的地方。一百多年后，比辽更北的金灭了北宋；再后来，比金更北的蒙古灭了南宋。你看到规律了吗？被轻视的对手，往往最危险。沈阳故宫的这群人，就是下一个“被轻视的对手”进化成的终极版本。', NULL),
('sy-01', 'su-dongpo', 'su-b', 0, 'sy-01-su-b-l1', '这道门比我想象的矮了许多。我在汴京时见惯了大宋宫城的巍峨，但转念一想——成吉思汗的蒙古包更小，照样踏平了半个天下。门的高度，从来不等于主人的高度。', NULL),
('sy-01', 'su-dongpo', 'su-b', 1, 'sy-01-su-b-l2', '顺治六岁那年，从这里走出去，翻过山海关，坐到紫禁城的龙椅上。一个孩子，未必知道自己跨过的不是门槛，是时代的裂缝。我六岁时在眉山老家，最远的门是院门口那扇竹篱笆。门越小，走出去的世界反而越大。', '门里门外的命运'),
('sy-01', 'su-dongpo', 'su-b', 2, 'sy-01-su-b-l3', '顺治是清朝入关后的第一个皇帝，但他的继位过程极其仓促。皇太极突然病逝，八旗内斗差点火并，最后妥协选了一个六岁孩子当皇帝——不是因为他多能干，恰恰是因为他最小，各方势力都觉得好控制。他从这扇门走出去时，坐在轿子里哭了一路，不是哭离别，是孩子想娘。而就是这个哭着出关的孩子，日后会在紫禁城写下“正大光明”四个字挂在乾清宫。沈阳故宫的每一扇门，送出去的都是还没完成的人，收进来的已经是历史了。', NULL),
('sy-02', 'sharp-elder', 'elder-a', 0, 'sy-02-elder-a-l1', '崇政殿，沈阳故宫的金銮殿。听着挺唬人，实际上就这么大——面阔五间，不如北京太和殿的十分之一。但就是在这小屋子里，皇太极改了国号，把“后金”变成了“大清”。这相当于一个沈阳的创业团队，在这间小办公室里宣布：我们要去纳斯达克敲钟了。', NULL),
('sy-02', 'sharp-elder', 'elder-a', 1, 'sy-02-elder-a-l2', '为啥要把“金”改成“清”？说法很多，最有意思的一种是：明朝的“明”字是日月当空，火气太旺；而“清”带三点水，水能克火。皇太极这是在做文字层面的心理战。还有一个原因——“金”会勾起汉人对靖康之耻的记忆，换个名字好办事。改名这事，皇太极比和珅的谐音梗用得早多了。', '皇太极的改名玄机'),
('sy-02', 'sharp-elder', 'elder-a', 2, 'sy-02-elder-a-l3', '1636年，皇太极在这里举行称帝大典，国号从“后金”改为“大清”，年号从“天聪”改为“崇德”。这两步走极其老练：“后金”是继承女真传统，但汉人一听“金”就想起了掳走徽钦二帝的靖康之耻；改为“清”，既保留了水的意象（满族发源于长白山天池，水是生命之源），又彻底和“金”做了切割。年号从“天聪”改成“崇德”，则是从“天命所归”转向了“以德服人”——他不再满足于当一个部落的可汗，他想当天下人的皇帝。名字不是符号，是政治宣言。', NULL),
('sy-02', 'sharp-elder', 'elder-b', 0, 'sy-02-elder-b-l1', '崇政殿，沈阳故宫的金銮殿。听着挺唬人，实际上就这么大——面阔五间，不如北京太和殿的十分之一。但就是在这小屋子里，皇太极改了国号，把“后金”变成了“大清”。这相当于一个沈阳的创业团队，在这间小办公室里宣布：我们要去纳斯达克敲钟了。', NULL),
('sy-02', 'sharp-elder', 'elder-b', 1, 'sy-02-elder-b-l2', '你看这殿顶，用的不是北京那种黄琉璃瓦，而是黄琉璃瓦剪绿边。黄代表皇家，绿代表什么呢？有人说是草原——这群人虽然盖了房子，但骨子里还惦记着那片绿。这颜色搭配，相当于一个创业CEO在办公室里挂了张大学宿舍的照片：富贵了，但不忘出身。', '这座殿的建筑秘密'),
('sy-02', 'sharp-elder', 'elder-b', 2, 'sy-02-elder-b-l3', '崇政殿还有一个极其罕见的特征——它的柱子是方的。中国传统宫殿建筑几乎全是圆柱，但沈阳故宫的崇政殿、大政殿，全部用方柱。方柱在结构上不如圆柱受力均匀，但它传达了一种草原民族的审美：帐篷的杆子是直的，草原上没有圆柱的概念。另外方柱上雕刻的龙纹也比北京故宫的更粗犷，龙爪是张开的，姿态是俯冲的——这不是养在深宫的龙，这是刚从长白山飞下来的龙，身上还带着松针味儿。', NULL),
('sy-02', 'su-dongpo', 'su-a', 0, 'sy-02-su-a-l1', '这间屋子让我想起自己当过的签书判官厅——房子不大，管的事不少。皇太极在这里做了一生中最大的决定。伟大决策往往诞生在小房间里，因为屋子越小，人的野心越容易把墙撑破。', NULL),
('sy-02', 'su-dongpo', 'su-a', 1, 'sy-02-su-a-l2', '把“后金”改成“大清”，看似一个文字游戏，实则是一次脱胎换骨。我当年建议神宗皇帝改元“元祐”，也是想借一个名字开启新气象。但大宋的积弊太深，改名字没用。皇太极能改成功，不是名字的功劳，是他真有那个实力托底。空有其名的改革叫折腾，名副其实的改名才是里程碑。', '改名的勇气'),
('sy-02', 'su-dongpo', 'su-a', 2, 'sy-02-su-a-l3', '皇太极改国号不只是换招牌，他同时做了几件极实在的事：设立内三院（后来的内阁雏形）、完善八旗制度、建立蒙古八旗和汉军八旗、推行满汉分治但同时又满汉通婚。他一边改名字，一边改制度，一边扩队伍。这三件事同时做，他才敢在这间小殿里宣告一个新的帝国诞生。我当年劝神宗皇帝变法，只推了一条青苗法就鸡飞狗跳——不是变法不对，是整个体制已经没有接受变法的弹性了。宋的悲剧在这里，清的幸运也在这里：一个制度还在少年期，怎么改都对；一个制度已经老态龙钟，改什么都疼。', NULL),
('sy-02', 'su-dongpo', 'su-b', 0, 'sy-02-su-b-l1', '这间屋子让我想起自己当过的签书判官厅——房子不大，管的事不少。皇太极在这里做了一生中最大的决定。伟大决策往往诞生在小房间里，因为屋子越小，人的野心越容易把墙撑破。', NULL),
('sy-02', 'su-dongpo', 'su-b', 1, 'sy-02-su-b-l2', '你可以想象皇太极和范文程他们在这里商量怎么打明朝的场景。一方小桌，一张羊皮地图，几个满汉谋士围坐，灯油烧到半夜。努尔哈赤在外面打仗，皇太极在这里想办法。建功立业不只在战场，更在这些不眠的夜晚。', '创业者的客厅'),
('sy-02', 'su-dongpo', 'su-b', 2, 'sy-02-su-b-l3', '范文程这个人值得一说。他是范仲淹的十七世孙，正经的北宋名臣后代，却投了后金，给努尔哈赤和皇太极当谋士。他参与了清朝几乎所有重大决策：入关、剃发易服、定都北京。一个汉人，帮满人设计了征服汉人的路径。后人骂他汉奸，但皇太极在崇政殿里对范文程执弟子礼，问无不答。范文程的选择，你可以唾弃，但你无法忽视一个事实：在明末那个烂到根的体制里，有才华的人找不到出路，而沈阳这间小殿给了他们一个白纸画图的机会。历史上最大的背叛，往往不是背叛者选的，是被背叛者自己推出去的。', NULL),
('sy-03', 'sharp-elder', 'elder-a', 0, 'sy-03-elder-a-l1', '凤凰楼，沈阳故宫最高的建筑，三层。别嫌矮，当年它可是盛京城的天际线——站在这楼顶上，全盛京城尽收眼底。皇太极在这儿办公、休息、看风景，有时也在这儿接见亲信。这楼相当于沈阳故宫的VIP会所。', NULL),
('sy-03', 'sharp-elder', 'elder-a', 1, 'sy-03-elder-a-l2', '凤凰楼的二楼，是皇太极的书房。清朝初年那些改变历史的诏书，有一大半是从这儿发出去的。打仗的方略、汉人的招抚政策、对朝鲜的外交文书——全在这小屋子里敲定。说白了，这是一个没有监控的密室，比崇政殿更适合说真话。', '楼不在高，有故事则灵'),
('sy-03', 'sharp-elder', 'elder-a', 2, 'sy-03-elder-a-l3', '皇太极有个习惯：在凤凰楼二楼议事时，不许记录官在场。他说“议事当尽言，有记录官在旁，人不敢尽言”。这个细节说明他深谙人性——人在被记录的时候，说话会自动切换成“将来可以公开”的版本。凤凰楼的私密性，让皇太极听到了更真实的意见。但这也带来了一个问题：我们今天研究清初历史，关于凤凰楼里的决策过程几乎没有任何原始记录。历史被刻意留白了，这座楼成了一个沉默的证人。', NULL),
('sy-03', 'sharp-elder', 'elder-b', 0, 'sy-03-elder-b-l1', '凤凰楼，沈阳故宫最高的建筑，三层。别嫌矮，当年它可是盛京城的天际线——站在这楼顶上，全盛京城尽收眼底。皇太极在这儿办公、休息、看风景，有时也在这儿接见亲信。这楼相当于沈阳故宫的VIP会所。', NULL),
('sy-03', 'sharp-elder', 'elder-b', 1, 'sy-03-elder-b-l2', '为什么叫凤凰楼？不是给皇后住的——皇后住清宁宫。这名字取自“凤凰涅槃”，皇太极在暗示什么，你品品：改国号为清，是涅槃；从部落汗变成皇帝，是涅槃。他在这楼上看盛京城，看到的不是房子，是他的蓝图。站在三楼的窗口往外看一眼，你脚下这一片，是清朝上市前的孵化器。', '凤凰的寓意'),
('sy-03', 'sharp-elder', 'elder-b', 2, 'sy-03-elder-b-l3', '还有一个民间说法：凤凰楼建在沈阳故宫中轴线的最高点，镇住了整座皇宫的风水。从大清门到崇政殿到凤凰楼，地势一级比一级高，到了凤凰楼达到顶点。这种步步高升的布局，在北京故宫是看不到的——北京故宫太和殿虽然高大，但地势是平的，靠台基硬抬起来。沈阳故宫是真的借了地势，把皇宫修在了一个缓坡上。创业初期的王朝，连风水都比别人多了一分自然的助力。', NULL),
('sy-03', 'su-dongpo', 'su-a', 0, 'sy-03-su-a-l1', '三层楼，在盛京已算摩天。皇太极在这里看他的江山，应该和我当年在超然台上看密州，是相似的感受——城郭如棋，百姓如蚁，而自己不过是个暂时执棋的人。登高望远的瞬间，人最容易同时感到豪迈和渺小。', NULL),
('sy-03', 'su-dongpo', 'su-a', 1, 'sy-03-su-a-l2', '我在密州修超然台时，朋友笑我：一个小州城的破台子，有什么好得意的。我回他：“凡物皆有可观”，台不在高，在眼界。皇太极在凤凰楼上看到的盛京，跟汴京、临安比就是个大村子，但他在这楼上看到的不只是眼前——他看到了山海关以南。一个人能看多远，不在于他站得多高，在于他敢不敢看。', '登高与望远'),
('sy-03', 'su-dongpo', 'su-a', 2, 'sy-03-su-a-l3', '皇太极在这楼上向北望，是他的龙兴之地长白山；向南望，是他志在必得的中原。这种“南北都能看见”的位置感极其重要。我在超然台上只能看到密州的城墙和远处的丘陵，但那个视野刚好能容纳我的全部忧愁和全部释然。凤凰楼提供给皇太极的，比视野更珍贵的是一个缓冲空间——在战场和寝宫之间，他需要一个能独自待着的地方。所有的决策者都需要这样一个地方，哪怕只有三层楼高。', NULL),
('sy-03', 'su-dongpo', 'su-b', 0, 'sy-03-su-b-l1', '三层楼，在盛京已算摩天。皇太极在这里看他的江山，应该和我当年在超然台上看密州，是相似的感受——城郭如棋，百姓如蚁，而自己不过是个暂时执棋的人。登高望远的瞬间，人最容易同时感到豪迈和渺小。', NULL),
('sy-03', 'su-dongpo', 'su-b', 1, 'sy-03-su-b-l2', '凤凰，百鸟之王。皇太极给这座楼命名时，心里想的不只是吉祥——雄为凤，雌为凰，凤凰合体，阴阳调和。一个从马背上起家的民族，开始讲究阴阳调和了，这说明他要的不再只是打天下，而是要坐天下了。马上得天下易，马下治天下难。', '名字之重'),
('sy-03', 'su-dongpo', 'su-b', 2, 'sy-03-su-b-l3', '从“后金”到“大清”是从武功到文治的转身，凤凰楼的命名是这种转身的空间象征。努尔哈赤时代，后金的核心建筑是汗王宫和大政殿，那是打仗和议政的地方，没有“文化地标”。皇太极建凤凰楼，特意把藏书、字画、典籍搬上二楼和三楼。他在这里收藏汉文典籍，命人翻译《三国演义》为满文，把汉人的智慧当兵法研读。一个征服者在凤凰楼上读被征服者的书——这个画面，比他坐在龙椅上更让人敬畏。', NULL),
('sy-04', 'sharp-elder', 'elder-a', 0, 'sy-04-elder-a-l1', '皇太极的卧室，清宁宫。一个大清的开国皇帝，就睡在这种地方。你看这门，不大；窗户，不大；整间屋子放在北京故宫就是个偏殿的规格。可你知道吗？皇太极就是在这儿，睡到第五十二年的某一天，突然就没了。正史说“无疾而终”，翻译成白话就是：加班猝死。', NULL),
('sy-04', 'sharp-elder', 'elder-a', 1, 'sy-04-elder-a-l2', '你往屋里看——能看到炕不？对，沈阳故宫的帝后寝宫里有火炕，北京故宫可没有这玩意儿。满族人怕冷，从长白山带来的生活习惯，当了皇帝也改不了。皇太极睡的是南炕，暖和；皇后哲哲睡北炕，差点意思。一张炕的位置，就是后宫地位的晴雨表。', '清宁宫的设计秘密'),
('sy-04', 'sharp-elder', 'elder-a', 2, 'sy-04-elder-a-l3', '清宁宫的火炕不是简单的取暖工具，它是满族民居的核心生活空间。满族人的炕上，吃饭、待客、睡觉、议事全在一张大炕上。皇太极在这炕上接见过蒙古王爷，也在炕上跟皇后哲哲吃过家常饭。这间屋子既是一个国家的决策室，也是一对夫妻的客厅。和紫禁城乾清宫那种“皇上在哪儿都有规矩”的空间布局完全不同，清宁宫把帝王的公私空间合二为一了——还没学会“端”，还没学会把生活和工作分开。这是沈阳故宫最迷人的地方：它还没来得及学会伪装。', NULL),
('sy-04', 'sharp-elder', 'elder-b', 0, 'sy-04-elder-b-l1', '皇太极的卧室，清宁宫。一个大清的开国皇帝，就睡在这种地方。你看这门，不大；窗户，不大；整间屋子放在北京故宫就是个偏殿的规格。可你知道吗？皇太极就是在这儿，睡到第五十二年的某一天，突然就没了。正史说“无疾而终”，翻译成白话就是：加班猝死。', NULL),
('sy-04', 'sharp-elder', 'elder-b', 1, 'sy-04-elder-b-l2', '皇太极死的时候五十二岁，前一天还在处理政务，晚上就没了。死因？流传最广的说法是“心痛”——不是失恋的心痛，是心脑血管疾病。他太累了。四十多岁才称帝，然后没享过一天福，不是在打仗就是在准备打仗。沈阳故宫这群人，从努尔哈赤到皇太极，都没活到享福的年纪。创业第一代，往往是用命换江山。', '猝死的皇帝'),
('sy-04', 'sharp-elder', 'elder-b', 2, 'sy-04-elder-b-l3', '崇德八年（1643年）八月初九，皇太极白天在崇政殿召见了蒙古土默特部使者，又去凤凰楼批了几道折子，晚上回到清宁宫，坐在南炕上突然“无疾崩”。随行的《清实录》只有四个字：“端坐而崩。”现代医学推测，大概率是主动脉夹层或者大面积心梗。他常年征战留下的旧伤、中年发福、满族贵高油高盐的饮食、以及不眠不休的工作节奏，全都压在那根细细的血管壁上。五十二岁，正是政治家的黄金年龄，但他的身体在创业阶段提前透支了。凤凰楼再高，够不着天；江山再大，换不回一根好血管。', NULL),
('sy-04', 'su-dongpo', 'su-a', 0, 'sy-04-su-a-l1', '这间屋子有火炕。我在黄州的冬天，屋里也砌了一个土炕，第一次睡差点把自己烤熟。后来学会了控制火候，冬夜裹着被子在炕上读书，觉得人生至此，夫复何求。皇太极在这炕上想的是什么？江山还是家人？大约二者皆有，因为帝王也是人。', NULL),
('sy-04', 'su-dongpo', 'su-a', 1, 'sy-04-su-a-l2', '南炕是热的，北炕差一些。皇太极和皇后的炕，一个温暖一个微凉，就像他们的关系——哲哲是政治联姻的蒙古公主，给足了尊荣，但真正的温度未必在南炕。我在眉山老家没有炕，冬天靠的是母亲煮的一碗姜汤。温度这东西，从来不是来自火，来自人心。', '炕上的温度'),
('sy-04', 'su-dongpo', 'su-a', 2, 'sy-04-su-a-l3', '皇太极一生娶了十五位后妃，地位最高的哲哲是正宫皇后，但最受宠的却是宸妃海兰珠。海兰珠二十六岁才入宫——在当时已是“高龄”——但皇太极对她用情极深，在崇政殿旁专门为她建了关雎宫。关雎，取自《诗经》第一首，是爱情的象征。海兰珠病重时，皇太极正在前线督战，听到消息抛下军队快马加鞭赶回，但还是没见到最后一面。他抱着宸妃的遗体痛哭，几天水米不进，大臣们跪了一地求他保重。这个在战场上从不退缩的男人，在清宁宫的炕上蜷缩成一团。所以说，帝王也是人，只是他的眼泪比别人更重——重到压垮历史书里所有关于他的“英明神武”。', NULL),
('sy-04', 'su-dongpo', 'su-b', 0, 'sy-04-su-b-l1', '这间屋子有火炕。我在黄州的冬天，屋里也砌了一个土炕，第一次睡差点把自己烤熟。后来学会了控制火候，冬夜裹着被子在炕上读书，觉得人生至此，夫复何求。皇太极在这炕上想的是什么？江山还是家人？大约二者皆有，因为帝王也是人。', NULL),
('sy-04', 'su-dongpo', 'su-b', 1, 'sy-04-su-b-l2', '你看这清宁宫的陈设，远不如后来北京故宫的奢华。但正是这种简朴，让人心生敬意。这群人还没学会享福，所以还能打仗。我见过太多人，一旦安逸就开始堕落。大宋的皇帝们搬到临安后就再也不想回汴京——暖风熏得游人醉，直把杭州作汴州。皇太极的时代太短，短到他没机会变成那样。', '简朴的力量'),
('sy-04', 'su-dongpo', 'su-b', 2, 'sy-04-su-b-l3', '开国皇帝和守成皇帝的寝室，差的不只是面积，是整个生命状态。努尔哈赤和皇太极的沈阳故宫，睡的是火炕；康熙乾隆的北京故宫，睡的是龙床。炕能治老寒腿，床只能生富贵病。满人入关后，从第四代康熙开始就不睡炕了，觉得土气。可一百多年后的道光皇帝，在紫禁城乾清宫里冻得发抖也舍不得烧炭——那时候的大清已经不是创业时的大清了。一个王朝的兴衰，看皇帝的卧室就够了。', NULL),
('sy-05', 'sharp-elder', 'elder-a', 0, 'sy-05-elder-a-l1', '看见这根木头杆子没？索伦杆，满族人祭天用的神器。杆子顶上有锡斗，逢年过节往里放猪的内脏碎米，喂乌鸦。为什么喂乌鸦？因为传说乌鸦救过努尔哈赤的命。沈阳故宫每一处都在告诉你：别忘了我们从哪来。', NULL),
('sy-05', 'sharp-elder', 'elder-a', 1, 'sy-05-elder-a-l2', '满人敬乌鸦，这个习俗汉族人完全看不懂——乌鸦在汉文化里是丧气的象征。但满族传说里，努尔哈赤被明军追杀时，一群乌鸦落在他身上，追兵以为那是一具被乌鸦覆盖的尸体，就绕过去了。从此满族人世代敬鸦，不许打不许骂。一根杆子插在皇宫正中，每月的初一十五，皇帝亲自来喂。你说讲究不讲究？', '乌鸦救主'),
('sy-05', 'sharp-elder', 'elder-a', 2, 'sy-05-elder-a-l3', '这个故事还有一个版本：不是乌鸦，是喜鹊。说追兵放火烧林，一群喜鹊扑灭了努尔哈赤周围的火。不同版本的共同点是——黑色的鸟救了满族的开创者。但更深的象征含义是：满族来自山林，他们的庇护者不是龙，不是凤，而是森林里最不起眼的飞禽。索伦杆竖在清宁宫正前方，意味着皇帝的每一次祭天，面对的不是繁复的儒家仪轨，而是祖先与自然之间最原始的契约。这根杆子是整个沈阳故宫最有“满族性”的物件，北京故宫没有。', NULL),
('sy-05', 'sharp-elder', 'elder-b', 0, 'sy-05-elder-b-l1', '看见这根木头杆子没？索伦杆，满族人祭天用的神器。杆子顶上有锡斗，逢年过节往里放猪的内脏碎米，喂乌鸦。为什么喂乌鸦？因为传说乌鸦救过努尔哈赤的命。沈阳故宫每一处都在告诉你：别忘了我们从哪来。', NULL),
('sy-05', 'sharp-elder', 'elder-b', 1, 'sy-05-elder-b-l2', '祭天这事儿，汉族皇帝也干，但那叫“天子祭天”，是天经地义的。满族人是半路出家当皇帝，得反复向臣民证明自己“受命于天”。索伦杆上的每一次祭祀，都是一场无声的加冕仪式。这杆子不高，但它撑着的，是一个王朝的合法性。', '祭天的政治含义'),
('sy-05', 'sharp-elder', 'elder-b', 2, 'sy-05-elder-b-l3', '皇太极规定，每月初一、十五，皇帝亲自主持索伦杆祭天仪式。整个过程不设供桌、不烧香、不念祭文，就是皇帝亲手把碎肉和米放进锡斗，然后退后三步行三跪九叩大礼。这种仪式的简洁性，和北京天坛祭天的繁复程度完全是两个极端。它保留了一种“人跟老天爷面对面说话”的原始感。一个值得注意的细节：清入关后，顺治在北京皇宫里也立了索伦杆。故宫的坤宁宫门前就有一根，这是紫禁城里唯一的满族萨满教遗存。从沈阳到北京，这根杆子跟着走了两千里路。', NULL),
('sy-05', 'su-dongpo', 'su-a', 0, 'sy-05-su-a-l1', '一根木杆，上面顶着锡斗喂乌鸦。我在儋州时，黎族同胞也有类似的习俗——在村口立一根图腾柱，逢节祭拜。可见天下民族，各有各的源头，但感恩的心是相通的。忘本的人走不远，记住了来处，才知道往哪去。', NULL),
('sy-05', 'su-dongpo', 'su-a', 1, 'sy-05-su-a-l2', '汉人厌恶乌鸦，满人敬奉乌鸦。同一种鸟，两种命运，只因一个传说。我在乌台诗案后，看谁都像乌鸦。后来想通了——别人怎么看你，往往和你无关，和他们的需要有关。满人需要乌鸦，所以乌鸦就是神鸟；汉人不需要，所以乌鸦就是扫把星。', '乌鸦与偏见'),
('sy-05', 'su-dongpo', 'su-a', 2, 'sy-05-su-a-l3', '在汉文化中，乌鸦被污名化不是一开始就有的。先秦时期，乌鸦是孝鸟——“乌鸟私情，愿乞终养”说的是乌鸦反哺的孝道。到了唐代以后，乌鸦才逐渐变成不祥之兆。这个变化很有意思：文化越成熟，对自然的解读越负面。满族因为靠近自然，保留了对乌鸦的朴素情感。有时候，所谓的“文明”，就是对自然的长期背叛。索伦杆让我想起一个命题：一个民族最珍贵的，可能不是他后来学会的，而是他最初就相信的东西。', NULL),
('sy-05', 'su-dongpo', 'su-b', 0, 'sy-05-su-b-l1', '一根木杆，上面顶着锡斗喂乌鸦。我在儋州时，黎族同胞也有类似的习俗——在村口立一根图腾柱，逢节祭拜。可见天下民族，各有各的源头，但感恩的心是相通的。忘本的人走不远，记住了来处，才知道往哪去。', NULL),
('sy-05', 'su-dongpo', 'su-b', 1, 'sy-05-su-b-l2', '这根杆子是一个提醒：无论走多远，别忘了是谁救过你。我的救命恩人是一个无名狱卒——乌台诗案我被关押时，他偷偷给我送纸笔。我至今不知道他的名字。皇太极每次喂乌鸦时，大概也在心里念着努尔哈赤——那个开创一切的人。', '祭祀与记忆'),
('sy-05', 'su-dongpo', 'su-b', 2, 'sy-05-su-b-l3', '努尔哈赤死于1626年宁远之战后的同年，病逝于返回沈阳的途中。他打了一辈子仗，统一了女真各部，创立了八旗制度，但没来得及入关。皇太极每次在索伦杆前祭拜时，天上有乌鸦飞过，他看到的应该是父亲未完的遗志。我没有为祖父苏序守过孝——他在我出生前就去世了——但我为他写过墓志铭。祭祀的本质，不是让死去的人复活，是让活着的人不要忘了自己是谁。沈阳故宫这根杆子，就是整个清朝的身份证。', NULL),
('sy-06', 'sharp-elder', 'elder-a', 0, 'sy-06-elder-a-l1', '大政殿，沈阳故宫最标志性的建筑。八角攒尖顶，八个面，代表八旗。满人的所有政治密码都在这座殿里了——八旗议政，军事民主，大汗也只是其中一票。这和汉族皇帝的金銮殿逻辑上完全相反：一个是聚拢权力，一个是分摊权力。', NULL),
('sy-06', 'sharp-elder', 'elder-a', 1, 'sy-06-elder-a-l2', '你见过哪个中国皇宫的正殿是八角的？没有。太和殿是长方形，面阔十一间，典型的中原礼制。这八角大政殿是帐篷的变体——早期满人的议政之所就是个八面开窗的大帐篷，大汗和各旗旗主围坐一圈。皇太极把它用砖石固定下来，但保留了八面的象征。这里面藏着一个最本质的区别：草原的政权，权力是分布在圆周上的；中原的政权，权力是集中在一个点上的。', '八角形的秘密'),
('sy-06', 'sharp-elder', 'elder-a', 2, 'sy-06-elder-a-l3', '八角形的建筑在中国古典建筑中极为罕见。除了沈阳故宫大政殿，另一个著名的八角建筑是北京天坛的祈年殿，那是祭天的礼制建筑。大政殿把八角形用于政治建筑，寓意明确：八旗如同一把撑开的伞，八面各顶一角，谁也不能独大。努尔哈赤时期，八旗旗主共议国政，大汗的权威靠的是军功和威望，不是制度赋予的独裁权。皇太极虽然后来削弱了旗主们的权力，但他选择了保留这八角的格局，而不是拆掉重建一个方形的金銮殿。这既是对传统的尊重，也是一种政治智慧：有些东西，面上不能改。', NULL),
('sy-06', 'sharp-elder', 'elder-b', 0, 'sy-06-elder-b-l1', '大政殿，沈阳故宫最标志性的建筑。八角攒尖顶，八个面，代表八旗。满人的所有政治密码都在这座殿里了——八旗议政，军事民主，大汗也只是其中一票。这和汉族皇帝的金銮殿逻辑上完全相反：一个是聚拢权力，一个是分摊权力。', NULL),
('sy-06', 'sharp-elder', 'elder-b', 1, 'sy-06-elder-b-l2', '你站在大政殿门口往前看，两边各五座亭子，一共十座，叫十王亭。这不是装饰，是八旗旗主加左右翼王的办公桌。努尔哈赤开会时，大汗坐正中大政殿，各旗主坐自己对应方向的亭子里，有事出列，没事归位。这套议事制度，比明朝的早朝高效多了——它等于把各事业部负责人放在同一个院子里，有问题当场拍板。', '十王亭的排列'),
('sy-06', 'sharp-elder', 'elder-b', 2, 'sy-06-elder-b-l3', '八旗制度本质上是军政合一的管理体系。每旗相当于一个独立的事业部，旗主管理旗内的户籍、征兵、赋税和司法。打仗时，一旗就是一支军队；平时，一旗就是一个行政单位。这十王亭在大政殿前的排列，正好形成了一个“决策闭环”：大汗居中，八旗环绕，左翼王和右翼王分列左右。任何重大决策，旗主们在各自亭子里就能当场表态，不需要走繁复的汇报流程。明末的朝廷决策链条有多长？内阁票拟、司礼监批红、六科给事中封驳——等到一项决策走完流程，前线可能已经换了三任主帅。所以有时候效率不是靠制度，是靠物理距离——大家在一个院子里喊一嗓子就行。', NULL),
('sy-06', 'su-dongpo', 'su-a', 0, 'sy-06-su-a-l1', '八角大政殿，八面来风。我在朝中做官多年，太熟悉那种“一言堂”的压抑了。满人这套八旗议政，虽有它的缺陷，但在某些方面竟比大宋的朝会制度更接近“议”这个字的原意——大家坐下来，真的在商量。', NULL),
('sy-06', 'su-dongpo', 'su-a', 1, 'sy-06-su-a-l2', '方是规矩，圆是包容。大政殿用八角形接近了圆——没有谁的方向是绝对的正面，每个人都有自己的角度。中原王朝的大殿永远是方正的，皇帝面对正南，臣子分列东西——每一块砖都在强调等级。而在这里，八旗旗主围坐，地位相近，大汗不过是其中之一。这种平等感，在汉族政治里从没存在过。', '圆的智慧'),
('sy-06', 'su-dongpo', 'su-a', 2, 'sy-06-su-a-l3', '宋朝的朝会有个荒唐的规定：大臣启奏时必须面向皇帝，不能侧身。有一次我因为朝服太紧扭了脖子，回话时偏了一下头，被御史弹劾“失仪不恭”。我心想，我回的是军国大事，你弹劾我站姿不好——这种制度下，能议出什么好政策？沈阳故宫的十王亭布局，在物理上消解了这种“唯天子是瞻”的空间结构。八旗旗主面向大政殿时，看到的不只是大汗，还能看到彼此的脸。一个彼此能对视的议事空间，和一个只能看皇帝后脑勺的空间，产生的是完全不同的政治文化。', NULL),
('sy-06', 'su-dongpo', 'su-b', 0, 'sy-06-su-b-l1', '八角大政殿，八面来风。我在朝中做官多年，太熟悉那种“一言堂”的压抑了。满人这套八旗议政，虽有它的缺陷，但在某些方面竟比大宋的朝会制度更接近“议”这个字的原意——大家坐下来，真的在商量。', NULL),
('sy-06', 'su-dongpo', 'su-b', 1, 'sy-06-su-b-l2', '八旗议政在创业期极其高效，但它有一个致命缺陷：一旦大汗不够强势，这套分权系统就会变成内斗温床。皇太极死后，多尔衮和豪格的权力争夺差点让大清分裂。分权与集权，是所有组织的永恒难题。太分则乱，太合则僵，唯一的解药是——人。制度再完美，人的素质不够，也是白搭。', '效率与专制的博弈'),
('sy-06', 'su-dongpo', 'su-b', 2, 'sy-06-su-b-l3', '1643年皇太极突然去世，没有留下继位遗诏。八旗内部立刻分裂成两大阵营：两黄旗拥立皇太极长子豪格，两白旗拥立皇太极的弟弟多尔衮。双方在大政殿前僵持不下，剑拔弩张，差点兵戎相见。最后妥协的结果是：谁都不当，让皇太极六岁的第九子福临继位，就是后来的顺治。多尔衮和济尔哈朗共同辅政。这个决定是在大政殿的密室里达成的，但八旗议政的制度框架给了它合法性。创业时代的“分权”制度，在换代时变成了内斗的导火索。清朝后来入关后逐步削弱八旗权力，到雍正建立军机处——从八角形回归了方正。这个建筑的命运，就是清朝政治体制的缩影。', NULL),
('sy-07', 'sharp-elder', 'elder-a', 0, 'sy-07-elder-a-l1', '终于到了个不同的地方——文溯阁。你注意看它的瓦，全沈阳故宫都是黄琉璃瓦，只有这一座用的是黑色琉璃瓦。这不是没钱换，是故意的。五行里黑色属水，而藏书阁最怕火。这配色是乾隆的旨意：用水的颜色克火，保佑《四库全书》平安。', NULL),
('sy-07', 'sharp-elder', 'elder-a', 1, 'sy-07-elder-a-l2', '《四库全书》一共抄了七部，分藏全国七座藏书阁。沈阳文溯阁得了其中一部，是乾隆特意赏给龙兴之地的。这份面子，北京故宫都没有——北京的文渊阁是给皇上自己看的，文溯阁是给祖宗看的。乾隆的意思是：祖宗啊，咱们不光能打，也能读书了。', '《四库全书》与沈阳'),
('sy-07', 'sharp-elder', 'elder-a', 2, 'sy-07-elder-a-l3', '文溯阁的名字本身就大有来头——“溯”是回溯源头的意思，“文溯”就是沿着文脉往回追溯。乾隆把七部《四库全书》分别命名为文渊、文源、文津、文溯、文汇、文澜、文宗，每一个名字都带一个“水”偏旁。藏书阁取名“水”意，是因为书最怕火——前面说的黑瓦五行属水也是同一个逻辑。但《四库全书》的命运比乾隆想的更曲折。文溯阁这部书后来几经辗转，曾因战乱迁到甘肃，又差点被苏联红军当战利品运走，最后落户兰州。沈阳人现在看到的文溯阁里，已经不是当年那部书了。但这个黑色的屋顶还在，还在忠实地执行着乾隆给它下达的五行命令。', NULL),
('sy-07', 'sharp-elder', 'elder-b', 0, 'sy-07-elder-b-l1', '终于到了个不同的地方——文溯阁。你注意看它的瓦，全沈阳故宫都是黄琉璃瓦，只有这一座用的是黑色琉璃瓦。这不是没钱换，是故意的。五行里黑色属水，而藏书阁最怕火。这配色是乾隆的旨意：用水的颜色克火，保佑《四库全书》平安。', NULL),
('sy-07', 'sharp-elder', 'elder-b', 1, 'sy-07-elder-b-l2', '文溯阁是乾隆年间才建的，离皇太极那会儿已经一百多年了。这时候的大清已经不是当初那个只会打仗的部落了——他们开始修书、藏书、刻书。从大政殿到文溯阁，就是从马上到纸上。一个民族的成熟，从他把刀放下、拿起书开始算。', '从武功到文治'),
('sy-07', 'sharp-elder', 'elder-b', 2, 'sy-07-elder-b-l3', '沈阳故宫里，文溯阁是唯一的“外来者”——它的建筑年代（1782年）比其他建筑晚了近一个半世纪。皇太极到乾隆，中间隔了顺治、康熙、雍正三代。乾隆选择在盛京的祖庭建一座藏书阁，与其说是告慰祖先，不如说是在完成一种文化上的“补课”：乾隆知道汉族知识分子打心底看不起满人的文化根基，所以他要用《四库全书》这样的超级工程来证明——你们有的，我们也有了，而且做得比你们更全。但这种“补课心态”本身就值得玩味：一个人拼命证明自己不是别人口中的样子，恰恰说明他还在意别人的评价。真正自信的人，不需要用一座黑色屋顶的房子来证明自己读过书。', NULL),
('sy-07', 'su-dongpo', 'su-a', 0, 'sy-07-su-a-l1', '黑瓦藏书阁，这是我今天见到最动人的建筑。水色为黑，用以克火，护住书。我一生藏书不少，可惜乌台诗案时，夫人一气之下烧了我大半诗稿。书怕火，更怕人心里的火——嫉妒之火、恐惧之火、政治之火。', NULL),
('sy-07', 'su-dongpo', 'su-a', 1, 'sy-07-su-a-l2', '《四库全书》收录了三千多种典籍，但也禁毁了大量书籍，尤其是涉及辽金元“蛮夷”的记载，以及对满人祖先女真不利的文字。修书的同时也在毁书。这座黑瓦下的殿堂，既保存了文明，也执行了审查。我若生在乾隆朝，我的“大江东去”大概也会因为里面有“乱石穿空，惊涛拍岸”这种过于激烈的句子而被删改。幸还是不幸？我在宋朝已经遭了足够的罪。', '书的命运'),
('sy-07', 'su-dongpo', 'su-a', 2, 'sy-07-su-a-l3', '乾隆修《四库全书》耗时十余年，动用了三千多名抄写员，是古代史上最大规模的文化工程。但同一时期，清朝销毁了约三千种、十余万部书籍——比《四库全书》本身的数量还大。销毁的理由五花八门：提到女真、契丹、蒙古的早期历史，删；对清朝有负面评价，删；甚至有些书只是因为作者是明朝遗民，删。文溯阁黑瓦底下藏的，是中国历史上最浩大的文化工程，也是最彻底的言论清洗。书的双面命运全浓缩在这座建筑里。我的诗在乌台诗案时被夫人烧掉大半，她说那些诗是“惹祸的根苗”。我当时恨她，后来明白了——她烧的何尝不是一种护？只是乾隆的护法是禁别人的书，我夫人的护法是烧我的诗。前者为了江山，后者为了一个家。', NULL),
('sy-07', 'su-dongpo', 'su-b', 0, 'sy-07-su-b-l1', '黑瓦藏书阁，这是我今天见到最动人的建筑。水色为黑，用以克火，护住书。我一生藏书不少，可惜乌台诗案时，夫人一气之下烧了我大半诗稿。书怕火，更怕人心里的火——嫉妒之火、恐惧之火、政治之火。', NULL),
('sy-07', 'su-dongpo', 'su-b', 1, 'sy-07-su-b-l2', '乾隆在这里建藏书阁，是想告诉后人：这个民族不光有铁骑，还有文心。我钦佩这种自觉——一个成熟的文明，最终都会走向对知识的敬畏。但同时我也警觉：当文化被用作象征，它就可能不再是文化本身，而成了装饰。黑瓦很美，但愿瓦下的书，真有人在读。', '龙兴之地的文脉'),
('sy-07', 'su-dongpo', 'su-b', 2, 'sy-07-su-b-l3', '清代皇帝的文化策略有个显著特点：什么都做得很“满”——规模要大，品级要高，象征意义要一目了然。文溯阁的建筑规格极高，整个沈阳故宫只有它的瓦换了颜色。《四库全书》的抄写标准也极严，错一个字就要重抄整册。但一个疑问是：乾隆对书的形式如此讲究，他本人真的需要查阅沈阳这套《四库全书》吗？他一生到过沈阳四次，每次停留不过数日，文溯阁对他来说更多是一个文化路标而非真正的书房。我说这话不是苛责——文化有时候就需要一些路标。但路标立好之后，有人沿着路走进书里去吗？那是另一个更难回答的问题了。', NULL),
('sy-08', 'sharp-elder', 'elder-a', 0, 'sy-08-elder-a-l1', '看见这根烟囱没？沈阳故宫最高的人工构筑物，比凤凰楼还高。但它不是瞭望塔，它就是根烟囱——给整个皇宫供暖系统排烟用的。满人把取暖看得比什么都重，宁可让烟囱比皇帝的办公楼高。实用主义，刻在骨子里。', NULL),
('sy-08', 'sharp-elder', 'elder-a', 1, 'sy-08-elder-a-l2', '沈阳的冬天零下二三十度，没暖气宫殿就是冰窖。沈阳故宫从努尔哈赤那会儿就修了完整的地暖系统——火地。地面下铺设烟道，烧火的暖气通过烟道把整个地面烘热，最后从这根烟囱排出去。这套技术比北京故宫的地暖还早。北京故宫的地暖叫“地炕”，就是跟沈阳学的。', '一宫之暖'),
('sy-08', 'sharp-elder', 'elder-a', 2, 'sy-08-elder-a-l3', '沈阳故宫的火地系统是满族民居取暖技术的集大成者。原理很简单：在房间地下砌上纵横交错的烟道，室外烧火口投柴，热气在烟道里循环，把方砖地面烤热，最后从烟囱排烟。一间清宁宫，地下烟道长度接近二十米，室内温度能保持在十五度以上。在当年的技术水平下，这已经是顶级的“恒温系统”了。但它的代价是——每天要有人在天亮前两个小时起来烧炕，填柴、清灰、控温，不能间断。皇太极的温暖睡眠，是一群守夜人用整夜不睡换来的。烟囱冒出的每一缕烟，都是一个普通人的寒冷夜晚。', NULL),
('sy-08', 'sharp-elder', 'elder-b', 0, 'sy-08-elder-b-l1', '看见这根烟囱没？沈阳故宫最高的人工构筑物，比凤凰楼还高。但它不是瞭望塔，它就是根烟囱——给整个皇宫供暖系统排烟用的。满人把取暖看得比什么都重，宁可让烟囱比皇帝的办公楼高。实用主义，刻在骨子里。', NULL),
('sy-08', 'sharp-elder', 'elder-b', 1, 'sy-08-elder-b-l2', '这根烟囱在清朝还有个名字叫“通天柱”。满族传说里，天和地之间本来有根柱子连着，后来断了，人类就回不去天上了。烟囱是“通天柱”的人间替代品——烟升上天，就是把人间的心愿带给天神。所以沈阳故宫的烟囱修得特别高，既是实用，也是信仰。', '烟囱的象征'),
('sy-08', 'sharp-elder', 'elder-b', 2, 'sy-08-elder-b-l3', '沈阳故宫这根烟囱一共十层，每层六块砖，总共六十块砖，象征一甲子。烟囱基座刻有莲花纹，顶上是葫芦形——莲花是佛教圣物，葫芦是道教的法器，满族萨满教的烟囱把佛道两家都给调和了。一根烟囱上融合了三种信仰，沈阳故宫的杂糅气质在这根柱子上达到了顶点。这也是清朝后来能统一中国的原因之一：它不是排斥异己，而是把所有异己都整合进自己的体系里，连烟囱都不放过。', NULL),
('sy-08', 'su-dongpo', 'su-a', 0, 'sy-08-su-a-l1', '一根烟囱比皇帝的书房还高。我在黄州的茅屋里，烟囱是竹子编的，一烧就冒浓烟，呛得我眼泪直流。但那种烟是活的，有温度的。这座高大的烟囱让我想起一句话：真正的文明不是看你最高的楼有多高，是看你最普通的烟囱冒不冒烟。', NULL),
('sy-08', 'su-dongpo', 'su-a', 1, 'sy-08-su-a-l2', '宫殿通常是冰冷的——高大的石柱、空旷的大殿、庄严的仪式，都让人觉得自己渺小。但这根烟囱提醒你：皇宫也是要生火做饭的，皇帝也是要暖炕的。一缕炊烟，把皇宫从天上拉回了人间。我写诗偏爱日常之物——柴米油盐酱醋茶，样样可入诗。这根烟囱如果让我来写，会比大政殿更有诗意。', '烟火气与宫殿气'),
('sy-08', 'su-dongpo', 'su-a', 2, 'sy-08-su-a-l3', '我在黄州时写过一首《猪肉颂》，专讲怎么炖红烧肉。一个被贬的官员写菜谱，同僚觉得丢人，我却觉得——诗如果只能写庙堂和山水，不能写灶台和炊烟，那诗就死了半条命。沈阳故宫这根烟囱，在我看来比它的金銮殿更值得写。因为它关联的不是皇权的宏大叙事，而是每一个冬天早晨烧炕的人的手上的冻疮。一个诗人应该能看到那个烧炕的人，而不只是住在炕上的人。', NULL),
('sy-08', 'su-dongpo', 'su-b', 0, 'sy-08-su-b-l1', '一根烟囱比皇帝的书房还高。我在黄州的茅屋里，烟囱是竹子编的，一烧就冒浓烟，呛得我眼泪直流。但那种烟是活的，有温度的。这座高大的烟囱让我想起一句话：真正的文明不是看你最高的楼有多高，是看你最普通的烟囱冒不冒烟。', NULL),
('sy-08', 'su-dongpo', 'su-b', 1, 'sy-08-su-b-l2', '烟从下往上走，正如人的祈愿。但还有一种东西是从上往下走的——粮食、温暖、雨水。烟囱是上升的，地暖是下沉的。一上一下之间，一个家就活了。治国也是一样——有上的雄心，更要有下的关怀。皇太极在凤凰楼上眺望天下，而底下烧炕的人，从未出现在他的视野里。', '向上与向下'),
('sy-08', 'su-dongpo', 'su-b', 2, 'sy-08-su-b-l3', '皇太极的改革中有一项容易被人忽略：他改善了盛京城的城市供暖和粮食供给体系。他在沈阳城外修了粮仓，城内修了排水渠，连驻防八旗的家属过冬用多少柴薪都有定量配给。这些不是史书里会大书特书的功绩，但正是这些“看不见的事”，让一个边陲小城撑起了一个帝国。烟囱冒烟不是小事——一座城的人都吃得上热饭，住得了暖屋，这个政权才有资格谈未来。历史更喜欢记录战争和大殿，却忽略了粮食和温度。而历史真正的动力，往往就藏在这些被忽略的东西里。', NULL),
('sy-09', 'sharp-elder', 'elder-a', 0, 'sy-09-elder-a-l1', '颐和殿，一个最容易被游客跳过的殿。它不大，不气派，甚至有点寒碜。但就是在这里，乾隆四次回盛京祭祖时，住的都是这间。堂堂乾隆，在北京住那么大的紫禁城，回到老家就住这儿——不是装低调，是真低调。他在这儿睡的不是龙床，是炕。', NULL),
('sy-09', 'sharp-elder', 'elder-a', 1, 'sy-09-elder-a-l2', '乾隆一生来了盛京四次，每次都要在颐和殿住上几天。他在北京是皇帝，在这儿是孙子——这儿供着他的祖宗。他在颐和殿里写的诗，明显比他在北京写得老实，少了那种“十全老人”的嘚瑟，多了点晚辈的恭敬。一个人不管官多大，回到老家都得收着点。', '乾隆的盛京情结'),
('sy-09', 'sharp-elder', 'elder-a', 2, 'sy-09-elder-a-l3', '乾隆第一次东巡是1743年，他三十二岁，意气风发。他在颐和殿里写下了《盛京赋》，追述祖先创业的艰辛，全文洋洋洒洒三千多字，是他一生中最长的赋。有趣的是，这篇赋里没有一句提到他自己的功绩，全在写努尔哈赤和皇太极。后来他修四库全书时，特意把《盛京赋》收录进去，排在集部之首。一个人在自己的盛年，愿意把笔墨全都留给祖辈——这不是自谦，这是知道自己的位置。乾隆的可爱，就藏在这间不起眼的殿里。他在北京可以当“十全老人”，在沈阳只能当“努尔哈赤的曾孙”。', NULL),
('sy-09', 'sharp-elder', 'elder-b', 0, 'sy-09-elder-b-l1', '颐和殿，一个最容易被游客跳过的殿。它不大，不气派，甚至有点寒碜。但就是在这里，乾隆四次回盛京祭祖时，住的都是这间。堂堂乾隆，在北京住那么大的紫禁城，回到老家就住这儿——不是装低调，是真低调。他在这儿睡的不是龙床，是炕。', NULL),
('sy-09', 'sharp-elder', 'elder-b', 1, 'sy-09-elder-b-l2', '乾隆四次东巡，每次排场都不小，花销巨大，但目的很明确：告诉满人，别忘了祖宗。入关一百多年后，北京的八旗子弟已经开始提笼架鸟、斗蛐蛐了，骑射荒废。乾隆把大家拉回盛京看一看先辈住的地方，是一种精神喊话：别丢了老满人的魂。可惜，这种喊话效果有限——老家永远在，但走远的人回不去。', '祭祖的政治学'),
('sy-09', 'sharp-elder', 'elder-b', 2, 'sy-09-elder-b-l3', '乾隆第四次东巡时，已经七十三岁，白发苍苍。他最后一次走进颐和殿，据说在炕沿上坐了很久，没有说话。随行大臣不敢催，都在殿外等着。没人知道那几分钟里他想什么。是想起少年时第一次来盛京的新鲜？还是预感到大清正在走下坡路？他知道自己不会再来第五次了。颐和殿的朴素，对晚年的乾隆来说可能是一种奢侈——在北京太和殿的高大台阶上，他找不到一个可以安静坐着的地方。而这间小殿的炕沿上，他可以什么都不是，只是一个快走不动的老人。', NULL),
('sy-09', 'su-dongpo', 'su-a', 0, 'sy-09-su-a-l1', '乾隆回盛京住这里，就像我回眉山老家住旧屋。外面的世界再大，回到原点时，人都会变小——变小不是贬义，是把那些不必要的膨胀卸下来。我在眉山老宅的院子里，还保留着我小时候写字的那张石桌，歪歪扭扭刻着我的名字。', NULL),
('sy-09', 'su-dongpo', 'su-a', 1, 'sy-09-su-a-l2', '我一生漂泊，回眉山的次数屈指可数。每次回去，都会去父母坟前坐一整天。不是做给别人看，是真的有很多话想说。乾隆来盛京祭祖，大概也是如此——做了几十年皇帝，心里积了多少话，只能在祖宗面前无声地说。千里迢迢跑来住一间朴素的殿，图的不是排场，是那一会儿的安静。', '回乡是一种仪式'),
('sy-09', 'su-dongpo', 'su-a', 2, 'sy-09-su-a-l3', '乾隆在东巡途中，随行人员超过三千人，马车绵延数十里，每到一处州县都要地方供应粮草。有人说他东巡是劳民伤财的作秀。我无意替乾隆辩护，但我想说：一个人到了老年，愿意花几个月的时间在路上颠簸，只为了回到祖辈的旧屋子住几天——这份心意本身并不虚伪。奢侈的不是他，是他必须带着的那套“皇帝”装备。如果他不是皇帝，大概会一个人骑一头驴回来，在炕上睡一晚，第二天清早悄悄走。颐和殿存在的意义，是给他一个从“皇帝”暂时退下来的机会。', NULL),
('sy-09', 'su-dongpo', 'su-b', 0, 'sy-09-su-b-l1', '乾隆回盛京住这里，就像我回眉山老家住旧屋。外面的世界再大，回到原点时，人都会变小——变小不是贬义，是把那些不必要的膨胀卸下来。我在眉山老宅的院子里，还保留着我小时候写字的那张石桌，歪歪扭扭刻着我的名字。', NULL),
('sy-09', 'su-dongpo', 'su-b', 1, 'sy-09-su-b-l2', '沈阳故宫对乾隆来说是老家，对我来说，眉山是老家。但你知道吗，我后半辈子再也没能长住眉山。不是不想，是不能。人在仕途，身不由己。乾隆也是如此——他不能久留盛京，北京有太多事等他。老家永远在等你，你也永远想回去，但总有比回家更重要的事。', '老家与远方'),
('sy-09', 'su-dongpo', 'su-b', 2, 'sy-09-su-b-l3', '我在海南儋州时，离眉山三千里，那时候我六十多岁了，知道自己可能再也回不去了。我在儋州盖了一间小房子，故意把它盖成眉山老屋的样子——一样的格局，一样的朝向，院子里一样种了竹子。住进去第一夜，我恍惚觉得回到了七岁，母亲在隔壁房间织布。醒来才知道是海浪声。乾隆在颐和殿住的几夜，大概也有类似的恍惚。权力的巅峰是孤独的，而故乡是唯一能让孤独停靠几夜的地方。即使这故乡只是祖先替你选择的，不是你自己长大的，它也比你正坐着的那把龙椅更接近大地。', NULL),
('sy-10', 'sharp-elder', 'elder-a', 0, 'sy-10-elder-a-l1', '逛完了。沈阳故宫不大，但每一个角落都在说一句话：“我是从草原来的。”从十王亭的帐篷痕迹到清宁宫的火炕，从索伦杆的乌鸦崇拜到大政殿的八角形状，他们没忘本。北京故宫是给别人看的，沈阳故宫是给自己住的。', NULL),
('sy-10', 'sharp-elder', 'elder-a', 1, 'sy-10-elder-a-l2', '如果把北京故宫和沈阳故宫放在一起比较，你会发现一个扎心的事实：沈阳故宫是创业者盖的，每块砖都在说“我要活下去”；北京故宫是继承者盖的，每块砖都在说“我是天子”。一个王朝的生命力，从建筑就能看出来。当建筑开始炫耀，这个王朝就老了。从沈阳到北京，满人用了十九年；从入住北京到八旗子弟提笼架鸟，用了不到一百年。', '两个故宫的对话'),
('sy-10', 'sharp-elder', 'elder-a', 2, 'sy-10-elder-a-l3', '有一组数据很刺眼：努尔哈赤起兵时，八旗兵总兵力只有六万，打下了整个辽东。皇太极时期扩大到二十万，征服了蒙古和朝鲜。顺治入关时，满洲八旗加上蒙古汉军，总兵力约十八万，征服了一亿人口的明朝。但仅仅六十年后，康熙亲征准噶尔时，八旗兵已经不能独立作战，要靠绿营汉兵当主力。再过一百年的乾隆朝，八旗子弟的考核成绩惨不忍睹——骑马射箭，十发五中就算优秀。从沈阳故宫到北京故宫的两百里路，一个民族走掉了自己最珍贵的东西。沈阳故宫就是那种东西的寄存处，可惜存得再好，没人回来取。', NULL),
('sy-10', 'sharp-elder', 'elder-b', 0, 'sy-10-elder-b-l1', '逛完了。沈阳故宫不大，但每一个角落都在说一句话：“我是从草原来的。”从十王亭的帐篷痕迹到清宁宫的火炕，从索伦杆的乌鸦崇拜到大政殿的八角形状，他们没忘本。北京故宫是给别人看的，沈阳故宫是给自己住的。', NULL),
('sy-10', 'sharp-elder', 'elder-b', 1, 'sy-10-elder-b-l2', '很多人觉得沈阳故宫就是个“小北京故宫”，来不来无所谓。我跟你说，不来沈阳故宫，你看不懂北京故宫。因为北京故宫里的很多谜，答案都在沈阳。比如为什么坤宁宫有根索伦杆，为什么乾清宫有火炕的痕迹，为什么清朝皇帝偏爱蒙古后妃——这些问题，你在北京只能看到结果，在沈阳能看到原因。', '沈阳的意义'),
('sy-10', 'sharp-elder', 'elder-b', 2, 'sy-10-elder-b-l3', '现在你从这道门走出去，外面就是沈阳最热闹的中街，高楼商场奶茶店。三百多年前，这扇门外是盛京城的土路，冬天雪能没膝。皇太极站在凤凰楼上看到的不是LED广告屏，是无尽的林海雪原和那个他永远打不到的南方。从这道门出过的人，有的进了北京当了皇帝，有的战死在宁远城外，有的老死在盛京的冷宫里。一道门送走了整个清朝两百六十八年的起承转合。沈阳故宫从来不是北京故宫的“小号版”，它是北京故宫的子宫。而你刚才走了一个多小时的那条路，一个民族走了十九年。够快的了。', NULL),
('sy-10', 'su-dongpo', 'su-a', 0, 'sy-10-su-a-l1', '沈阳故宫，看完了。你觉得它和北京故宫比，哪一个更好？我告诉你：不用比。一个是你年轻时的出租屋，虽然小，但每一件家具都是亲手挣来的；另一个是你功成名就后的大宅子，气派但冷。我更喜欢这里——因为这里还能闻到人的味道。', NULL),
('sy-10', 'su-dongpo', 'su-a', 1, 'sy-10-su-a-l2', '小不一定不如大。我的赤壁赋是在一条小船上写的，不是在什么巍峨的殿宇里。沈阳故宫的小，反而让它更真实。你在这里能看到人怎么取暖、怎么做饭、怎么祭天。北京故宫把这一切都藏起来了，藏得太好，反而忘了为什么出发。从沈阳到北京，从十三副铠甲到九五大位，真正的力量不在终点，在出发时的那个念头。', '小与大的哲学'),
('sy-10', 'su-dongpo', 'su-a', 2, 'sy-10-su-a-l3', '努尔哈赤起兵时只有十三副铠甲。十三副铠甲打天下——这不是演义，这是清实录里的记载。他统一建州女真时，手底下的人连像样的铁器都不够，箭镞用骨头磨。皇太极在沈阳故宫的凤凰楼上批折子时，还在为铁矿的产量发愁。两代人之后，他的曾孙乾隆在北京紫禁城里为一块玉玺的印泥颜色不合心意而发火。从缺铁到挑剔印泥的颜色，这个距离叫“忘了来路”。沈阳故宫小到不会让你忘记任何事，因为炕就在你眼前，烟囱就在你头顶，索伦杆就竖在你必经的路中央。北京故宫大到让你忘了一切，因为它把所有的“不容易”都抹平了。', NULL),
('sy-10', 'su-dongpo', 'su-b', 0, 'sy-10-su-b-l1', '沈阳故宫，看完了。你觉得它和北京故宫比，哪一个更好？我告诉你：不用比。一个是你年轻时的出租屋，虽然小，但每一件家具都是亲手挣来的；另一个是你功成名就后的大宅子，气派但冷。我更喜欢这里——因为这里还能闻到人的味道。', NULL),
('sy-10', 'su-dongpo', 'su-b', 1, 'sy-10-su-b-l2', '你来沈阳故宫，未必是为了学历史。你可能只是正好在沈阳，正好有空，就来了。但我想告诉你——你来的这个地方，是一群人不甘心一辈子待在山林里，咬着牙走向未知世界的起点。它不华丽，但它真实。你在这里呼吸的空气，和当年那些人呼吸的是同一片。这就够了。', '你的故宫'),
('sy-10', 'su-dongpo', 'su-b', 2, 'sy-10-su-b-l3', '今天陪你走这一路，我在想一个问题：为什么现代人愿意花钱买票，在大太阳底下排队，挤在人堆里看一堆几百年前的旧房子？我想了很久，可能是这样的——你们的生活太快了。快到来不及想自己从哪里来，到哪里去。而这些旧房子不会动，不会催你，不会弹广告，它们只是静静地站在那里，等你自己走过去，然后在你耳边说一句只有你听得见的话。那一句话可能不是历史知识，不是建筑风格，而是——“慢下来，别急。”我不知道你刚才在哪个角落听到过这句话，但我希望你有。哪怕只有一秒钟。沈阳故宫很小，但那一秒钟很大。', NULL);
